AB = "https://support.apple.com/guide/business/"
for k, (s, t) in {"ab_signup": ("sign-up-and-verify-your-organization-axm402206497", "Sign up for Apple Business"),
                  "ab_renamed": ("../apple-business-connect/apple-business-connect-is-now-apple-business-abcb205640e7", "Apple Business Connect is now Apple Business"),
                  "ab_locations": ("about-locations-axm993232a60", "About locations in Apple Business"),
                  "ab_addloc": ("add-a-single-location-abcb98816a34", "Add a single location in Apple Business"),
                  "ab_accuracy": ("maintain-location-information-accuracy-abcb91c1d565", "Maintain location information accuracy with Apple Business"),
                  "ab_attrs": ("configure-location-attributes-abcbdc543423", "Configure location attributes in Apple Business"),
                  "ab_photos": ("add-edit-or-delete-photos-abcb7557e4c4", "Add, edit, or delete photos in Apple Business"),
                  "ab_cover": ("about-the-cover-photo-abcb139fcd45", "About the cover photo in Apple Business"),
                  "ab_showcase": ("create-your-first-showcase-abcb04e20054", "Create your first showcase in Apple Business"),
                  "ab_actions": ("about-actions-abcba5e65376", "About Actions in Apple Business"),
                  "ab_insights": ("use-insights-for-a-single-location-abcbb749656b", "Use insights for a single location in Apple Business"),
                  "ab_mail": ("intro-to-branded-mail-abcb761b19d2", "Intro to Branded Mail in Apple Business"),
                  "ab_ttp": ("intro-to-tap-to-pay-on-iphone-abcb5ea93db9", "Intro to Tap to Pay on iPhone in Apple Business"),
                  "ab_ads": ("promote-your-business-on-apple-maps-axm0ea9f3f95", "Promote your business on Apple Maps with Apple Business")}.items():
    url = (f"https://support.apple.com/guide/apple-business-connect/{s.split('/')[-1]}/web" if s.startswith("..")
           else f"{AB}{s}/1/web/1")
    SRC[k] = {"title": f"Apple Business User Guide: {t}", "url": url}

