INSIGHTS = L("Apple Business insights", "apple-business-insights")
MAIL = L("Apple Branded Mail", "apple-branded-mail")
TTP = L("Tap to Pay on iPhone for small business", "tap-to-pay-on-iphone-small-business")
ADS = L("ads on Apple Maps", "apple-maps-ads")
NAP = L("NAP consistency and local citations", "nap-consistency-local-citations")
GBP_LINKS = L("Google Business Profile booking and order links", "google-business-profile-links")
